def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    gaps = {}

    # Locate single-cell gaps between matching colored segments in rows.
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color and grid[r][c] == 0 and grid[r][c + 1] == color:
                gaps.setdefault(c, []).append((r, color))

    for c, bars in gaps.items():
        bars.sort()

        # Extend each gap's bar color upward, or to the preceding bar.
        previous = -1
        for r, color in bars:
            for rr in range(previous + 1, r + 1):
                out[rr][c] = color
            previous = r

        # Connect any vertical marker below the lowest bar to that bar.
        last_bar = bars[-1][0]
        marker = next(
            (rr for rr in range(last_bar + 1, h) if grid[rr][c] != 0),
            None
        )
        if marker is not None:
            color = grid[marker][c]
            for rr in range(last_bar + 1, marker):
                out[rr][c] = color

    return out
